import { GameOverScene } from "../scenes/game-over-scene";
import { GlitchGameScene } from "../scenes/game-scene";
import { GlitchPreloadScene } from "../scenes/glitch-preload-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadCardinalIslandScenes: SceneLoader = (game) => {
  game.scene.add(SCENE_KEYS.GLITCH_PRELOAD_SCENE, GlitchPreloadScene, false);
  game.scene.add(SCENE_KEYS.GLITCH_GAME_SCENE, GlitchGameScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.start(SCENE_KEYS.GLITCH_PRELOAD_SCENE);
};
