import { type TeamHuntState } from "@hunt/public-client";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import { PhaserGame } from "../../../rounds/overworld/gameworld/PhaserGame";
import { DataManager } from "../../../rounds/overworld/gameworld/common/data-manager";
import { loadCardinalIslandScenes } from "../../../rounds/overworld/gameworld/scene-loaders/cardinal-island";
import CardinalIslandBody from "./CardinalIsland";
import { type CardinalIslandState } from "./types";

const CardinalIslandManager = ({
  cardinalIslandState,
  initialTeamState,
}: {
  cardinalIslandState: CardinalIslandState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <CardinalIslandGameworldClient
      teamState={initialTeamState}
      cardinalIslandState={cardinalIslandState}
      render={({ gameNode }) => (
        <CardinalIslandBody teamState={initialTeamState} gameNode={gameNode} />
      )}
    />
  );
};

const elem = document.getElementById("glitch-cardinal-island-root");
if (elem) {
  const { initialGlitchCardinalIslandState, initialTeamState } =
    window as unknown as {
      initialGlitchCardinalIslandState: CardinalIslandState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <CardinalIslandManager
      cardinalIslandState={initialGlitchCardinalIslandState}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount Glitch Cardinal Island because #glitch-cardinal-island-root was nowhere to be found",
  );
}

type CardinalIslandGameworldClientProps = {
  cardinalIslandState: CardinalIslandState;
  teamState: TeamHuntState;
  render: (args: {
    cardinalIslandState: CardinalIslandState;
    teamState: TeamHuntState;
    gameNode: React.ReactNode;
  }) => React.ReactElement;
};

function CardinalIslandGameworldClient({
  cardinalIslandState,
  teamState,
  render,
}: CardinalIslandGameworldClientProps) {
  const [hasHydrated, setHasHydrated] = useState(false);
  const dataManagerRef = useRef<DataManager>();
  if (!dataManagerRef.current) {
    dataManagerRef.current = new DataManager();
  }
  const dataManager = dataManagerRef.current;
  if (!dataManager.getEventsOverride("NO")) {
    dataManager.setEventsOverride("NO", cardinalIslandState.events);
  }

  useEffect(() => {
    // Ensure SSR markup matches before mounting the Phaser game wrapper.
    setHasHydrated(true);
  }, []);

  const gameNode = useMemo(() => {
    if (!hasHydrated) {
      return null;
    }
    return (
      <PhaserGame
        teamState={teamState}
        dataManager={dataManager}
        roundSlug={"the_glitch"}
        sceneLoader={loadCardinalIslandScenes}
      />
    );
  }, [dataManager, hasHydrated, teamState]);

  return (
    <>
      {render({
        cardinalIslandState,
        teamState,
        gameNode,
      })}
    </>
  );
}
