import CARDINAL_ISLAND_LEVEL from "../assets/data/levels/cardinal_island/cardinal_island.json";
import CARDINAL_ISLAND_BACKGROUND from "../assets/data/levels/cardinal_island/cardinal_island_background.png";
import CARDINAL_ISLAND_FOREGROUND from "../assets/data/levels/cardinal_island/cardinal_island_foreground.png";
import CARDINAL_ISLAND_EVENTS from "../assets/data/levels/cardinal_island/events.json";
import CARDINAL_ISLAND_NPCS from "../assets/data/levels/cardinal_island/npcs.json";
import CARDINAL_ISLAND_READABLES from "../assets/data/levels/cardinal_island/readables.json";
import NO_IMG from "../assets/images/npcs/no.png";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class GlitchPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.GLITCH_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadGlitchAssets();
  }

  #loadGlitchAssets(): void {
    // Load cardinal island level
    this.load.image(
      ASSET_KEYS.CARDINAL_ISLAND_BACKGROUND,
      CARDINAL_ISLAND_BACKGROUND,
    );
    this.load.image(
      ASSET_KEYS.CARDINAL_ISLAND_FOREGROUND,
      CARDINAL_ISLAND_FOREGROUND,
    );
    this.load.tilemapTiledJSON(
      ASSET_KEYS.CARDINAL_ISLAND_LEVEL,
      CARDINAL_ISLAND_LEVEL,
    );
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, CARDINAL_ISLAND_READABLES);

    // Load NPCs
    this.load.image(ASSET_KEYS.NO, NO_IMG);

    // Load cardinal island events and NPCs
    this.load.json(ASSET_KEYS.EVENTS, CARDINAL_ISLAND_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, CARDINAL_ISLAND_NPCS);
  }
}
